"""The thirds UF template for the Lean bank check (lane C1L): generated by C1's checker (Theorem C template, prefix
n = 50, zero tail), certificates searched over the Lean catalogue `tableT ++ [LP1, LP2, R, S] ++ windows` by the
exact mirror, re-verified in the Lean form, and emitted as Bank/ThirdsContent/AutoUFData.lean (data + decide).
Constants: P_bad = 5, c_Fr <= 25, depth 64, C = 10^9 on every piece.  Usage: python -I -X utf8 emit_thirds_uf.py"""
import sys, math
from fractions import Fraction as F
from pathlib import Path
sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
C1 = HERE.parents[3].parents[1] / 'outputs/Compatibility programme/automatic-banks-2026-10-28/C1'
sys.path.insert(1, str(C1))
import mirror as X
import gen_thirds_check as G
import emit_thirds as E
import checker as CK

OUT = G.WORK / 'CatalanCore/Uniform/Bank/ThirdsContent/AutoUFData.lean'
CBIG = F(10) ** 9


def catalogue(wins):
    names = [n for n, _ in X.BASE] + ['S'] + [f'W{a}_{b}' for a, b in wins]
    cat = [b for _, b in X.BASE] + [X.UFS] + [X.window(a, b) for a, b in wins]
    return names, cat


def build(wins):
    names, cat = catalogue(wins)
    bk = CK.Bank('thirds', True)
    T = CK.generated_templates(bk, 50, CBIG, P_bad=5)
    q, al = 3, F(3, 20)
    D = dict(q=3, M=6, al=al, members=[1, 2], depth=64, cF=25, Pbad=5, alpha0=F(23, 10), tau=None,
             alpha0b=F(23, 10), t0=F(3, 1000), cat=cat, iD6=5, tmpls={})
    used = set()
    for j, (t1, pieces) in T.items():
        ka = F(j, q)
        rows = []
        for P in pieces:
            r = G.search(P, cat, names, q, al, ka, D['depth'], D['cF'], D['Pbad'])
            assert r is not None, ('no certificate', j, P[:4])
            _, cert, _ = r
            used.add(names[cert[0]])
            for _, y, _ in cert[2]:
                used.add(names[y])
            rows.append((P, cert))
        D['tmpls'][j] = (t1, rows)
    D['tau'] = max(D['tmpls'][j][1][-1][0][1] for j in D['tmpls'])
    D['Lam'] = sum(X.mass(D['alpha0'], *D['tmpls'][j]) for j in D['tmpls']) / len(D['tmpls'])
    return D, names, used


HEADER = '''import CatalanCore.Uniform.Content.BankShared.Check.Bank
import CatalanCore.Uniform.Content.BankShared.Check.UF
import CatalanCore.Uniform.Content.BankShared.Check.Test
set_option Elab.async false
set_option maxRecDepth 100000

/-! # Data: the thirds UF template for the bank check (lane C1L)

Generated by `scripts/claude/bank/check/emit_thirds_uf.py`: C1's Theorem C template for thirds with UF (prefix
`n = 50`, the maximal affine runs of the profile minimum, the zero tail), certificates over the catalogue
`tableT ++ [LP1, LP2, R, S] ++ windows`, verified by the exact mirror.  `P_bad = 5`, `c_Fr ≤ 25`, depth `≤ 64`,
`C = 10⁹`.  `uf_check : check ufData = true`, one `decide +kernel` per chunk. -/

namespace CatalanCore.Uniform.Bank.ThirdsContent.AutoUF
open CatalanCore.Uniform.Content.BankShared.Check

/-- `n / d`. -/
abbrev qq (n : ℤ) (d : ℕ) : ℚ := Test.qq n d
'''


def lpiece(P):
    s, t, a, b, Cc = P
    return '⟨%s, %s, %s, %s, %s⟩' % tuple(E.lq(x) for x in (s, t, a, b, Cc))


def emit(D, T, wins, chunk=40):
    L = [HEADER]
    wl = ', '.join(f'brWin {a} {b}' for a, b in wins)
    L.append('/-- LP1, LP2, the rank branch, the UF branch and the M3D windows (indices 6, 7, 8, 9, 10, ...). -/\n'
             f'def ufExtra : List Branch := [brLP1, brLP2, brRank, brS, {wl}]\n')
    names = {}
    for j in sorted(T):
        rows = T[j][1]
        names[j] = []
        for ci in range(0, len(rows), chunk):
            nm = f'u{j}_{ci // chunk}'
            names[j].append(nm)
            body = ',\n  '.join('(%s, %s)' % (lpiece(P), E.lcert(c)) for P, c in rows[ci:ci + chunk])
            L.append(f'def {nm} : List (QPiece × Cert) := [\n  {body}]\n')
        L.append(f'def ufT{j} : QTmpl := ⟨qq 3 1000, {E.nest(names[j])}⟩\n')
    Lam, tau = D['Lam'], D['tau']
    L.append(f'''/-- The thirds UF bank data, with its finite `Λ_fin`. -/
def ufData : BankData where
  q := 3
  M := 6
  α := qq 3 20
  members := [1, 2]
  depth := 64
  cF := 25
  Pbad := 5
  α0 := qq 23 10
  τ := qq {tau.numerator} {tau.denominator}
  Λ := qq {Lam.numerator} {Lam.denominator}
  α0b := qq 23 10
  t0 := qq 3 1000
  extra := ufExtra
  tmpls := [{', '.join(f'({j}, ufT{j})' for j in sorted(T))}]
''')
    for j in sorted(T):
        for nm in names[j]:
            L.append(f'set_option profiler true in\ntheorem {nm}_ok : pieceAll ufData {j} {nm} = true := by decide +kernel\n')
        L.append(f'set_option profiler true in\ntheorem ufT{j}_head : tmplHead ufData {j} ufT{j} = true := by decide +kernel\n')
        oks = ', '.join(f'{nm}_ok' for nm in names[j])
        L.append(f'''theorem ufT{j}_ok : tmplOK ufData {j} ufT{j} = true := by
  unfold tmplOK
  rw [ufT{j}_head]
  show (true && pieceAll ufData {j} ({E.nest(names[j])})) = true
  simp only [pieceAll_append, {oks}, Bool.and_self]
''')
    tl = ', '.join(f'({j}, ufT{j})' for j in sorted(T))
    oks = ', '.join(f'ufT{j}_ok' for j in sorted(T))
    L.append(f'''set_option profiler true in
theorem uf_params : checkParams ufData = true := by decide +kernel

set_option profiler true in
theorem uf_classes : ufData.members.all (classOK ufData) = true := by decide +kernel

theorem uf_tmpls : ufData.tmpls.all (fun x => tmplOK ufData x.1 x.2) = true := by
  show [{tl}].all (fun x => tmplOK ufData x.1 x.2) = true
  simp only [List.all_cons, List.all_nil, {oks}, Bool.and_self]

/-- **The bank check accepts the thirds UF data.** -/
theorem uf_check : check ufData = true := by
  unfold check
  rw [uf_params, uf_tmpls, uf_classes]
  rfl

end CatalanCore.Uniform.Bank.ThirdsContent.AutoUF
''')
    OUT.write_text('\n'.join(L), encoding='utf-8')


if __name__ == '__main__':
    D, names, used = build(G.WINDOWS)
    wins = sorted({tuple(map(int, n[1:].split('_'))) for n in used if n.startswith('W')})
    D, names, used = build(wins)
    ok, st = X.check(D)
    assert ok, 'mirror check rejected'
    T = E.lean_form(D)
    E.unit_check(D, T)
    emit(D, T, wins)
    cnt = {n: 0 for n in names}
    for j in D['tmpls']:
        for _, c in D['tmpls'][j][1]:
            cnt[names[c[0]]] += 1
    print('windows', wins)
    print('pieces', {j: len(D['tmpls'][j][1]) for j in D['tmpls']}, 'tau', D['tau'])
    print('branch usage', {k: v for k, v in cnt.items() if v})
    print('max R_P', float(st['max_R_P']), 'max C_needed', float(st['max_C_needed']))
    print('Lam_fin', D['Lam'], float(D['Lam']))
    print('wrote', OUT)
